/** Selectable overlay years, newest first. */
export const OVERLAY_YEARS: number[] = Object.keys(YEAR_CURVES).map(Number).sort((a, b) => b - a);

const parsed = new Map<number, number[]>();
/** Decode one year's curve to percent. Memoised — called from render. */
export function yearCurve(year: number): number[] | null {
  const hit = parsed.get(year);
  if (hit) return hit;
  const raw = YEAR_CURVES[String(year)];
  if (!raw) return null;
  const out = raw.split(",").map((v) => Number(v) / 100);
  parsed.set(year, out);
  return out;
}

