export type MonthTable = {
  index: string[]; n: number[]; avg: number[]; median: number[];
  pos_pct: number[]; stdev: number[]; best: number[]; worst: number[];
};

export type Almanac = {
  meta: { symbol: string; start: string; end: string; trading_days: number; source: string };
  months: string[];
  monthTables: Record<string, MonthTable>;
  matrix: { years: number[]; data: (number | null)[][] };
  dow: Record<string, { index: string[]; n: number[]; avg: number[]; pos_pct: number[]; stdev: number[] }>;
  tdom: { index: string[]; all: number[]; modern: number[]; pos_all: number[]; pos_modern: number[] };
  tom: { window: string; n: number; avg_daily: number; pos_pct: number; annualized: number }[];
  sixMonth: { index: string[]; avg: number[]; median: number[]; pos_pct: number[]; best: number[]; worst: number[]; n: number[] };
  presidential: { index: string[]; n: number[]; avg: number[]; median: number[]; pos_pct: number[] };
  /** Cycle year x month mean return. Rows align with presidential.index. */
  presidentialMonth: { index: string[]; data: (number | null)[][] };
  decennial: { index: number[]; n: number[]; avg: number[]; median: number[]; pos_pct: number[] };
  decadeMonth: { index: number[]; data: (number | null)[][] };
  vol: { index: string[]; all: number[]; modern: number[]; avg_abs_all: number[]; avg_abs_modern: number[] };
  barometers: { signal: string; up_n: number; up_avg_full: number; up_hit: number; dn_n: number; dn_avg_full: number; dn_hit: number }[];
  now: {
    as_of: string;
    trading_day_of_year: number;
    rest_of_year: { era: string; n: number; avg: number; median: number; pos_pct: number; best: number; worst: number }[];
    window: { window: string; era: string; n: number; avg: number; median: number; pos_pct: number }[];
    sep_halves: { index: string[]; avg: number[]; median: number[]; pos_pct: number[]; n: number[] };
  };
};

